module updown_w2(input clk, input rst, input en, input up, output reg [1:0] count);
    // Reset and Enable conditions
    always @(*) begin
        if (rst) begin
            count <= 2'b00;
        end
        else if (en) begin
            if (up) begin
                count <= count + 1'b1;
            end
            else begin
                count <= count - 1'b1;
            end
        end
    end

    // Wraparound
    always @(*) begin
        if (count == 2'b11) begin
            count <= 2'b00;
        end
    end
